import { createClient } from "@supabase/supabase-js";
import postgres from "postgres";
import { createHash, randomUUID, randomBytes } from "node:crypto";
import { writeFileSync } from "node:fs";
import { batchDecisions, candidateRowsSchema } from "../../lib/import/batch";
import { stableId } from "../../lib/import/row";

process.loadEnvFile(".env.qa");
const db = postgres(process.env.SUPABASE_DB_URL!, { max: 2, onnotice: () => {} });
const admin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false, autoRefreshToken: false } });
type Row = { postedOn: string; description: string; amountMinor: bigint; externalId: string | null };
const log: unknown[] = [];

async function newWorkspace() {
  const created = await admin.auth.admin.createUser({ email: `qa-${randomUUID()}@example.invalid`, password: randomBytes(24).toString("hex"), email_confirm: true, user_metadata: { qa_test: "large-import" } });
  if (created.error) throw created.error;
  const user = created.data.user!.id;
  const [{ id }] = await db`select id from public.workspaces where owner_id=${user}`;
  return { user, workspace: id as string };
}

async function rpc(name: string, args: Record<string, unknown>) {
  const started = performance.now();
  const result = await admin.rpc(name, args);
  const ms = Math.round(performance.now() - started);
  if (result.error) throw Object.assign(new Error(`${name}: ${result.error.message} (${result.error.code}) after ${ms} ms`), { ms });
  return { data: result.data, ms };
}

export async function runImport(label: string, workspace: string, accountName: string, rows: Row[]) {
  const importId = randomUUID(), total = rows.length;
  const hash = createHash("sha256").update(label + randomUUID()).digest("hex");
  await db`insert into public.imports(id,workspace_id,filename,storage_path,file_hash,status,total_rows,mapping) values(${importId},${workspace},${label + ".csv"},${workspace + "/" + importId + ".csv"},${hash},'queued',${total},'{"rowContractVersion":"normalized-row-v1"}'::jsonb)`;
  const accountId = stableId(`${workspace}:account:${accountName}:EUR`), sourceId = stableId(`${workspace}:source:${accountId}`);
  await rpc("prepare_import_route", { p_import_id: importId, p_workspace_id: workspace, p_run_version: 1, p_account_id: accountId, p_source_id: sourceId, p_account_name: accountName, p_currency_code: "EUR", p_total_rows: total });
  const staged = rows.map((row, i) => ({ accountId, excluded: false, row: { sourceId: stableId(`${importId}:row:${i + 2}`), accountName, balanceId: stableId(`${importId}:balance:${i + 2}`), rowNumber: i + 2, calendarTimezone: null, sourceType: null, feeMinor: null,
    originalRow: { date: row.postedOn, description: row.description, amount: String(row.amountMinor), id: row.externalId ?? "" }, externalId: row.externalId, reviewReasons: [], feeEvidence: null, postedOn: row.postedOn, postedAt: null, description: row.description,
    amountMinor: row.amountMinor.toString(), currencyCode: "EUR", status: "posted", kind: "ordinary", merchantName: null, merchantNormalizedName: null, merchantId: null, categoryName: null, categoryId: null, balanceMinor: null, balanceAsOf: null } }));
  const [{ source_id, route_accounts, mapping }] = await db`select source_id,route_accounts,mapping from public.imports where id=${importId}`;
  const stage = await rpc("stage_import_rows", { p_import_id: importId, p_workspace_id: workspace, p_run_version: 1, p_file_hash: hash, p_mapping: mapping, p_routes: route_accounts, p_source_id: source_id, p_rows: staged });
  const batches: { offset: number; candidatesMs: number; ingestMs: number }[] = [];
  const started = performance.now();
  let failure: string | null = null;
  try {
    for (let offset = 0; offset < total; offset += 250) {
      const candidates = await rpc("import_batch_candidates", { p_import_id: importId, p_workspace_id: workspace, p_run_version: 1, p_offset: offset });
      const decisions = batchDecisions(candidateRowsSchema.parse(candidates.data));
      const ingest = await rpc("ingest_import_batch", { p_import_id: importId, p_workspace_id: workspace, p_run_version: 1, p_offset: offset, p_decisions: decisions });
      batches.push({ offset, candidatesMs: candidates.ms, ingestMs: ingest.ms });
    }
    await rpc("finish_import_run", { p_import_id: importId, p_workspace_id: workspace, p_run_version: 1, p_error: null });
  } catch (error) { failure = String(error); }
  const totalMs = Math.round(performance.now() - started);
  const [{ sources }] = await db`select count(*)::int sources from public.source_transactions where import_id=${importId}`;
  const [{ status, new_rows, matched_rows, review_rows }] = await db`select status,new_rows,matched_rows,review_rows from public.imports where id=${importId}`;
  const summary = { label, total, stageMs: stage.ms, totalMs, sources, status, new_rows, matched_rows, review_rows, failure,
    maxCandidatesMs: Math.max(0, ...batches.map(b => b.candidatesMs)), maxIngestMs: Math.max(0, ...batches.map(b => b.ingestMs)),
    first: batches.slice(0, 2), last: batches.slice(-2) };
  console.log(JSON.stringify(summary));
  log.push({ ...summary, batches });
  return { importId, accountId };
}

const merchants = Array.from({ length: 40 }, (_, i) => `Shop ${i}`);
const day = (i: number) => new Date(Date.UTC(2026, 9, 1) - (i % 730) * 86400000).toISOString().slice(0, 10);
const realistic = (prefix: string, n: number, start = 0): Row[] => Array.from({ length: n }, (_, k) => { const i = start + k; return { postedOn: day(i), description: merchants[i % 40], amountMinor: -BigInt(100 + (i * 37) % 9000), externalId: `${prefix}-${i}` }; });
const e2eShape = (n: number): Row[] => Array.from({ length: n }, (_, i) => ({ postedOn: "2026-09-01", description: `Synthetic expense ${String(i + 1).padStart(4, "0")}`, amountMinor: -101n, externalId: `controlled-${i + 1}` }));

const scenario = process.argv[2] ?? "all";
const users: string[] = [];
try {
  if (scenario === "fresh" || scenario === "all") {
    const { user, workspace } = await newWorkspace(); users.push(user);
    await runImport("fresh-e2e-5000", workspace, "Controlled cash", e2eShape(5000));
  }
  if (scenario === "large" || scenario === "all") {
    const { user, workspace } = await newWorkspace(); users.push(user);
    await runImport("seed-1-10000", workspace, "Main", realistic("bank", 10000));
    await runImport("seed-2-10000", workspace, "Main", realistic("bank", 10000, 10000));
    await runImport("overlap-5000", workspace, "Main", realistic("bank", 5000, 17500));
    await runImport("large-e2e-5000", workspace, "Controlled cash", e2eShape(5000));
  }
} finally {
  writeFileSync(`.qa/large-import/result-${scenario}-${Date.now()}.json`, JSON.stringify(log, null, 1));
  if (process.env.KEEP !== "1") for (const user of users) { await db`delete from public.workspaces where owner_id=${user}`.catch(e => console.error("workspace delete", String(e))); await admin.auth.admin.deleteUser(user); }
  await db.end();
}

