export async function cleanup(user: string) {
  await db.begin(async tx => {
    const [{ id: workspace }] = await tx`select id from public.workspaces where owner_id=${user}`;
    await tx`delete from public.transaction_sources where source_transaction_id in(select id from public.source_transactions where workspace_id=${workspace})`;
    for (const table of ["saved_analyses", "background_jobs", "import_control_events", "balance_snapshots", "transactions", "source_transactions", "import_staging", "imports", "data_sources", "accounts", "merchants", "categories"]) await tx`delete from ${tx("public." + table)} where workspace_id=${workspace}`;
    await tx`delete from public.workspaces where id=${workspace}`;
  });
  const removed = await admin.auth.admin.deleteUser(user);
  if (removed.error) throw removed.error;
}

