  from public.transactions t left join public.transaction_sources link on link.transaction_id=t.id left join public.source_transactions src on src.id=link.source_transaction_id
  where t.workspace_id=$1 and t.account_id=$2 and t.currency_code=$3 and t.posted_on=$4 and t.amount_minor=$5 and t.description=$6 and (src.id is null or (src.workspace_id=$1 and src.import_id<>$7))
