  from public.source_transactions src join public.transaction_sources link on link.source_transaction_id=src.id join public.transactions t on t.id=link.transaction_id
  where src.workspace_id=$1 and src.import_id<>$7 and src.external_id=$8 and t.workspace_id=$1 and t.account_id=$2 and t.currency_code=$3) x limit 1001;
