1	CREATE OR REPLACE FUNCTION public.ingest_import_row_internal(p_import_id uuid, p_workspace_id uuid, p_run_version integer, p_account_id uuid, p_row jsonb, p_review boolean)
2	 RETURNS jsonb
3	 LANGUAGE plpgsql
4	 SECURITY DEFINER
5	 SET search_path TO ''
6	AS $function$
7	declare imported public.imports%rowtype; source public.source_transactions%rowtype; canonical public.transactions%rowtype;
8	  source_id uuid; canonical_id uuid; balance_id uuid; action text; reasons text[]; merchant_id uuid; category_id uuid; merchant_name text; category_name text; linked_id uuid;
9	begin
10	  -- Correction/link RPCs lock canonical rows before recounting imports; preserve that lock order.
11	  if p_row is null or jsonb_typeof(p_row)<>'object' or octet_length(p_row::text)>11000000 then raise exception 'Invalid import row' using errcode='22023'; end if;
12	  canonical_id:=(p_row->>'transactionId')::uuid;
13	  perform id from public.transactions where id=canonical_id for update;
14	  if p_review then
15	    select * into strict imported from public.imports where id=p_import_id and workspace_id=p_workspace_id for update;
16	    if imported.status<>'completed' or imported.run_version is distinct from p_run_version then raise exception 'Import changed' using errcode='PT409'; end if;
17	  else
18	    imported:=public.lock_import_run(p_import_id,p_workspace_id,p_run_version);
19	  end if;
20	  -- Serialize overlapping imports through their final candidate check and insert.
21	  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_workspace_id::text||':'||p_account_id::text,0));
22	  source_id:=(p_row->>'sourceId')::uuid; balance_id:=(p_row->>'balanceId')::uuid; action:=p_row->>'action';
23	  if source_id is null or action is null or action not in ('new','matched','review') or (p_row->>'rowNumber')::integer is null or (p_row->>'rowNumber')::integer<2
24	    or jsonb_typeof(p_row->'originalRow') is distinct from 'object' or jsonb_typeof(p_row->'reviewReasons') is distinct from 'array'
25	    or p_row->>'currencyCode' is null or p_row->>'currencyCode'!~'^[A-Z]{3}$' or p_row->>'amountMinor' is null or p_row->>'amountMinor'!~'^-?[0-9]{1,19}$'
26	    or p_row->>'status' is null or p_row->>'status' not in ('posted','pending') or p_row->>'kind' is null or p_row->>'kind' not in ('ordinary','refund')
27	    or p_row->>'description' is null or length(p_row->>'description')>500 or p_row->>'postedOn' is null then raise exception 'Invalid import financial row' using errcode='22023'; end if;
28	  perform id from public.accounts where id=p_account_id and workspace_id=p_workspace_id and currency_code=p_row->>'currencyCode' and archived_at is null for share;
29	  if not found then raise exception 'Import account unavailable' using errcode='42501'; end if;
30	  select coalesce(array_agg(value),'{}') into reasons from jsonb_array_elements_text(p_row->'reviewReasons');
31	  insert into public.source_transactions(id,workspace_id,import_id,row_number,original_row,external_id,review_reasons,fee_evidence)
32	    values(source_id,p_workspace_id,p_import_id,(p_row->>'rowNumber')::integer,p_row->'originalRow',p_row->>'externalId',reasons,nullif(p_row->'feeEvidence','null'::jsonb)) on conflict(id) do nothing;
