56	        not exists(select 1 from public.transaction_sources l join public.source_transactions s on s.id=l.source_transaction_id where l.transaction_id=t.id and s.import_id=p_import_id)))) then raise exception 'Import candidates changed; retry with current evidence' using errcode='PT409'; end if;
57	    merchant_name:=nullif(btrim(p_row->>'merchantName'),''); category_name:=nullif(btrim(p_row->>'categoryName'),'');
58	    if merchant_name is not null then
59	      merchant_id:=(p_row->>'merchantId')::uuid;
60	      if merchant_id is null or length(merchant_name)>100 then raise exception 'Invalid import merchant' using errcode='22023'; end if;
