create index transactions_import_fingerprint_idx on public.transactions(workspace_id,account_id,posted_on,amount_minor,md5(description));

do $$
declare target record; definition text; occurrences integer;
begin
  for target in select * from (values
    ('public.import_batch_candidates(uuid,uuid,integer,integer)',
      'and t.posted_on=(item->''row''->>''postedOn'')::date and t.amount_minor=(item->''row''->>''amountMinor'')::bigint and t.description=item->''row''->>''description''',
      'md5(item->''row''->>''description'')'),
    ('public.ingest_import_batch(uuid,uuid,integer,integer,jsonb)',
      'and t.posted_on=(item->''row''->>''postedOn'')::date and t.amount_minor=(item->''row''->>''amountMinor'')::bigint and t.description=item->''row''->>''description''',
      'md5(item->''row''->>''description'')'),
    ('public.ingest_import_row_internal(uuid,uuid,integer,uuid,jsonb,boolean)',
      't.posted_on=(p_row->>''postedOn'')::date and t.amount_minor=(p_row->>''amountMinor'')::bigint and t.description=p_row->>''description''',
      'md5(p_row->>''description'')')
  ) fingerprint(signature,lookup,description_hash) loop
    definition:=pg_get_functiondef(target.signature::regprocedure);
    occurrences:=(length(definition)-length(replace(definition,target.lookup,'')))/length(target.lookup);
    if occurrences<>1 then raise exception 'Expected one import fingerprint lookup in %, found %',target.signature,occurrences; end if;
    execute replace(definition,target.lookup,target.lookup||' and md5(t.description)='||target.description_hash);
  end loop;
end;
$$;

